style.css:
body {
  background-color: #f8f2e9; /* soft beige */
  background-image: url('https://i.ibb.co/jh7Hjkf/christmas-pattern.png'); /* tileable doodle pattern */
  background-repeat: repeat;
  background-size: 250px;
  font-family: 'Quicksand', sans-serif;
  color: #2e2e2e;
  margin: 0;
  padding: 0;
  text-align: center;
}

/* Add snow overlay */
body::before {
  content: "";
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url("https://i.ibb.co/fdFhWwq/snowflake.png");
  background-repeat: repeat;
  opacity: 0.15;
  animation: snowfall 12s linear infinite;
  z-index: 0;
}

/* Titles with script look */
h1, h2, h3 {
  font-family: 'Dancing Script', cursive;
  font-size: 2.5rem;
  color: #40210f;
  margin: 20px 0;
  text-shadow: 1px 1px 3px rgba(0,0,0,0.2);
  position: relative;
  z-index: 1;
}

/* Buttons styled to match */
button {
  background-color: #c1272d;
  color: #fff;
  border: none;
  border-radius: 30px;
  padding: 12px 25px;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  margin: 10px;
  transition: 0.3s ease;
  position: relative;
  z-index: 1;
}

button:hover {
  background-color: #a11f24;
  box-shadow: 0 0 10px rgba(255,255,255,0.7);
  transform: scale(1.05);
}

/* Links styled cozy */
a {
  color: #c1272d;
  font-weight: bold;
  text-decoration: none;
  border-bottom: 2px dotted #c1272d;
  position: relative;
  z-index: 1;
}

a:hover {
  color: #006400;
  border-bottom-color: #006400;
}

/* Snow animation */
@keyframes snowfall {
  from { background-position: 0 -1000px; }
  to { background-position: 0 0; }
}
